queries.query:
find view "iacm:fct_workspace_events" w | filter w.created <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${workspace_filter_predicate} and ${provisioner_filter_predicate} and ${status_filter_predicate} and ${repository_filter_predicate}
| select { distinct_count(w.unique_id) as workspaces,
distinct_count(case when w.created >= cast(${start_time} as timestamp) then w.unique_id end) as new_in_window }

find view "iacm:fct_workspace_events" w | filter w.updated >= cast(${start_time} as timestamp) and w.created <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${workspace_filter_predicate} and ${provisioner_filter_predicate} and ${status_filter_predicate} and ${repository_filter_predicate}
| select { case when w.status is null or w.status = "" then "(none)" else w.status end as status,
distinct_count(w.unique_id) as workspaces } | group_by status | order_by workspaces desc

find view "view:pipeline:stage_execution" se | filter se.stage_type = "IACM" and se.is_deleted = false and se.start_ts >= cast(${start_time} as timestamp) and se.start_ts <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate}
| select { date_trunc("week", se.start_ts) as week, se.status as status, distinct_count(se.plan_execution_id) as executions }
| group_by week, status | order_by week asc

find view "iacm:fct_workspace_events" w | filter w.updated >= cast(${start_time} as timestamp) and w.created <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${workspace_filter_predicate} and ${provisioner_filter_predicate} and ${status_filter_predicate} and ${repository_filter_predicate}
| select { case when w.project is null or w.project = "" then "(none)" else w.project end as project, distinct_count(w.unique_id) as workspaces }
| group_by project | order_by workspaces desc | limit 15

find view "iacm:fct_workspace_events" w | filter w.updated >= cast(${start_time} as timestamp) and w.created <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${workspace_filter_predicate} and ${provisioner_filter_predicate} and ${status_filter_predicate} and ${repository_filter_predicate}
| select { case when w.provisioner_version is null or w.provisioner_version = "" then "unknown" else w.provisioner_version end as version,
w.provisioner as provisioner, distinct_count(w.unique_id) as workspaces }
| group_by version, w.provisioner | order_by workspaces desc | limit 30

find view "iacm:fct_workspace_events" w | filter w.updated >= cast(${start_time} as timestamp) and w.created <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${workspace_filter_predicate} and ${provisioner_filter_predicate} and ${status_filter_predicate} and ${repository_filter_predicate}
| select { w.project as project, w.status as status, distinct_count(w.unique_id) as workspaces }
| group_by w.project, w.status

find view "iacm:fct_workspace_events" w | filter w.created >= cast(${start_time} as timestamp) and w.created <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${workspace_filter_predicate} and ${provisioner_filter_predicate} and ${status_filter_predicate} and ${repository_filter_predicate}
| select { date_trunc("week", w.created) as week, w.provisioner as provisioner, distinct_count(w.unique_id) as new_workspaces }
| group_by week, w.provisioner | order_by week asc

find view "iacm:fct_workspace_events" w | filter w.created <= cast(${end_time} as timestamp) and w.updated < cast(${start_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${workspace_filter_predicate} and ${provisioner_filter_predicate} and ${status_filter_predicate} and ${repository_filter_predicate}
| select { w.identifier as workspace, w.name as name, w.org as org, w.project as project, w.status as status,
w.provisioner as provisioner, w.provisioner_version as version, w.updated as last_updated,
date_diff(w.updated, cast(${end_time} as timestamp), "day") as days_since_update }
| order_by days_since_update desc | limit 100

find entity "iacm:resource" r | join view "iacm:dim_resource_bindings" b on b.resource_id = r.id | join view "iacm:fct_workspace_events" w on w.identifier = b.binding_id and w.org = b.org and w.project = b.project | filter r.last_seen_millis_ts >= cast(${start_time} as timestamp) and r.last_seen_millis_ts <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${workspace_filter_predicate} and ${provisioner_filter_predicate} and ${status_filter_predicate} and ${repository_filter_predicate} and ${provider_filter_predicate}
| select { w.org as org, w.project as project, w.identifier as workspace, distinct_count(r.id) as resources,
distinct_count(case when r.mode = "managed" then r.id end) as managed,
round(100.0 * distinct_count(r.id) / sum(distinct_count(r.id)) over (), 1) as share_pct }
| group_by w.org, w.project, w.identifier | order_by resources desc | limit 50

find entity "iacm:resource" r | join view "iacm:dim_resource_bindings" b on b.resource_id = r.id | join view "iacm:fct_workspace_events" w on w.identifier = b.binding_id and w.org = b.org and w.project = b.project | filter r.last_seen_millis_ts >= cast(${start_time} as timestamp) and r.last_seen_millis_ts <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${workspace_filter_predicate} and ${provisioner_filter_predicate} and ${status_filter_predicate} and ${repository_filter_predicate} and ${provider_filter_predicate}
| select { case when date_diff(r.last_seen_millis_ts, cast(${end_time} as timestamp), "day") < 7 then "1. < 7d"
when date_diff(r.last_seen_millis_ts, cast(${end_time} as timestamp), "day") < 30 then "2. 7-30d"
when date_diff(r.last_seen_millis_ts, cast(${end_time} as timestamp), "day") < 90 then "3. 30-90d"
else "4. > 90d" end as freshness,
r.mode as mode, distinct_count(r.id) as resources }
| group_by freshness, r.mode | order_by freshness asc

find entity "iacm:resource" r | join view "iacm:dim_resource_bindings" b on b.resource_id = r.id | join view "iacm:fct_workspace_events" w on w.identifier = b.binding_id and w.org = b.org and w.project = b.project | filter r.last_seen_millis_ts >= cast(${start_time} as timestamp) and r.last_seen_millis_ts <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${workspace_filter_predicate} and ${provisioner_filter_predicate} and ${status_filter_predicate} and ${repository_filter_predicate} and ${provider_filter_predicate}
| select { r.provider_type as resource_type, r.mode as mode, distinct_count(r.id) as resources }
| group_by r.provider_type, r.mode

find entity "iacm:resource" r | join view "iacm:dim_resource_bindings" b on b.resource_id = r.id | join view "iacm:fct_workspace_events" w on w.identifier = b.binding_id and w.org = b.org and w.project = b.project | filter r.last_seen_millis_ts >= cast(${start_time} as timestamp) and r.last_seen_millis_ts <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${workspace_filter_predicate} and ${provisioner_filter_predicate} and ${status_filter_predicate} and ${repository_filter_predicate} and ${provider_filter_predicate}
| select { w.identifier as workspace, w.org as org, w.project as project, r.module as module,
r.provider_type as resource_type, r.name as name, r.mode as mode, r.provider as provider,
r.resource_id as cloud_id, r.sensitive_attribute_paths as sensitive_paths,
r.last_seen_millis_ts as last_seen }
| order_by workspace asc | limit 500

find view "iacm:dim_module" m | join view "iacm:fct_workspace_events" w on w.identifier = m.workspace and w.org = m.org and w.project = m.project | filter w.updated >= cast(${start_time} as timestamp) and w.created <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${workspace_filter_predicate} and ${provisioner_filter_predicate} and ${status_filter_predicate} and ${repository_filter_predicate} | filter m.module_key is not null
| select { m.module_source as module_source, distinct_count(concat(m.workspace, m.module_key)) as module_calls }
| group_by m.module_source | order_by module_calls desc

find view "iacm:dim_module" m | join view "iacm:fct_workspace_events" w on w.identifier = m.workspace and w.org = m.org and w.project = m.project | filter w.updated >= cast(${start_time} as timestamp) and w.created <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${workspace_filter_predicate} and ${provisioner_filter_predicate} and ${status_filter_predicate} and ${repository_filter_predicate} | filter m.module_key is not null
| select { m.module_key as module, m.module_version as version, distinct_count(m.workspace) as workspaces }
| group_by m.module_key, m.module_version

find view "view:pipeline:step_execution" st | filter st.step_type in ["IACMOpenTofuPlugin","IACMTerraformPlugin"] and st.start_ts >= cast(${start_time} as timestamp) and st.start_ts <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate}
| select { date_trunc("week", st.start_ts) as week, case when lower(st.step_identifier) in ["detectdrift","detect_drift"] then "Drift" when lower(st.step_identifier) in ["plandestroy","plan_destroy","tofu_destroy_plan"] then "Plan Destroy" when lower(st.step_identifier) in ["destroy","tofu_destroy","opentofu_destroy"] then "Destroy" when lower(st.step_identifier) in ["apply","tofu_apply","opentofu_apply"] then "Apply" when lower(st.step_identifier) in ["plan","tofu_plan","opentofu_plan","plan_refresh"] then "Plan" when lower(st.step_identifier) in ["init","opentofu_init","initialize"] then "Init" else "Other" end as command, count() as steps }
| group_by week, command | order_by week asc

find view "view:pipeline:stage_execution" se | filter se.stage_type = "IACM" and se.is_deleted = false and se.start_ts >= cast(${start_time} as timestamp) and se.start_ts <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate}
| inner join view "view:pipeline:step_execution" st on st.stage_execution_id = se.stage_execution_id
| select { st.step_type as step_type, st.status as status, count() as steps }
| group_by st.step_type, st.status | order_by steps desc

find view "view:pipeline:stage_execution" se | filter se.stage_type = "IACM" and se.is_deleted = false and se.start_ts >= cast(${start_time} as timestamp) and se.start_ts <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate}
| select { case when date_diff(date_trunc("week", se.start_ts), date_trunc("day", se.start_ts), "day") = 0 then "1 Mon" when date_diff(date_trunc("week", se.start_ts), date_trunc("day", se.start_ts), "day") = 1 then "2 Tue" when date_diff(date_trunc("week", se.start_ts), date_trunc("day", se.start_ts), "day") = 2 then "3 Wed"
when date_diff(date_trunc("week", se.start_ts), date_trunc("day", se.start_ts), "day") = 3 then "4 Thu" when date_diff(date_trunc("week", se.start_ts), date_trunc("day", se.start_ts), "day") = 4 then "5 Fri" when date_diff(date_trunc("week", se.start_ts), date_trunc("day", se.start_ts), "day") = 5 then "6 Sat"
else "7 Sun" end as weekday,
case when date_diff(date_trunc("day", se.start_ts), date_trunc("hour", se.start_ts), "hour") < 6 then "00-05 UTC" when date_diff(date_trunc("day", se.start_ts), date_trunc("hour", se.start_ts), "hour") < 12 then "06-11 UTC"
when date_diff(date_trunc("day", se.start_ts), date_trunc("hour", se.start_ts), "hour") < 18 then "12-17 UTC" else "18-23 UTC" end as hour_band,
count() as stages }
| group_by weekday, hour_band

find view "iacm:fct_workspace_events" w | filter w.updated >= cast(${start_time} as timestamp) and w.created <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${workspace_filter_predicate} and ${provisioner_filter_predicate} and ${status_filter_predicate} and ${repository_filter_predicate}
| select { w.repository as repository, distinct_count(w.unique_id) as workspaces }
| group_by w.repository | order_by workspaces desc | limit 15

find view "iacm:fct_workspace_events" w | filter w.updated >= cast(${start_time} as timestamp) and w.created <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${workspace_filter_predicate} and ${provisioner_filter_predicate} and ${status_filter_predicate} and ${repository_filter_predicate}
| select { case when w.provider_connector is null or w.provider_connector = "" then "(none)" else w.provider_connector end as connector,
w.provisioner as provisioner, distinct_count(w.unique_id) as workspaces }
| group_by connector, w.provisioner | order_by workspaces desc

find view "iacm:fct_workspace_events" w
| left join view "iacm:dim_tag" t on t.workspace = w.identifier and t.org = w.org and t.project = w.project
| filter w.updated >= cast(${start_time} as timestamp) and w.created <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${workspace_filter_predicate} and ${provisioner_filter_predicate} and ${status_filter_predicate} and ${repository_filter_predicate}
| select { 100.0 * distinct_count(case when t.tag_key is not null then w.unique_id end) / distinct_count(w.unique_id) as tagged_pct }

find view "iacm:dim_tag" t | join view "iacm:fct_workspace_events" w on w.identifier = t.workspace and w.org = t.org and w.project = t.project | filter w.updated >= cast(${start_time} as timestamp) and w.created <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${workspace_filter_predicate} and ${provisioner_filter_predicate} and ${status_filter_predicate} and ${repository_filter_predicate}
| select { t.tag_key as tag_key, case when t.tag_value = "" then "(empty)" else t.tag_value end as tag_value,
distinct_count(w.unique_id) as workspaces }
| group_by t.tag_key, tag_value

with iacm as (find view "view:pipeline:stage_execution" se | filter se.stage_type = "IACM" and se.is_deleted = false | select { se.plan_execution_id as pid, se.org_identifier as org, se.project_identifier as project } | group_by pid, org, project) find view "opa:policy_evaluation_result_view" p | inner join iacm i on i.pid = p.plan_execution_id | filter p.evaluation_created >= cast(${start_time} as timestamp) and p.evaluation_created <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate}
| select { date_trunc("day", p.evaluation_created) as day, p.policy_name as policy, count() as results }
| group_by day, p.policy_name | order_by day asc

with iacm as (find view "view:pipeline:stage_execution" se | filter se.stage_type = "IACM" and se.is_deleted = false | select { se.plan_execution_id as pid, se.org_identifier as org, se.project_identifier as project } | group_by pid, org, project) find view "opa:policy_evaluation_result_view" p | inner join iacm i on i.pid = p.plan_execution_id | filter p.evaluation_created >= cast(${start_time} as timestamp) and p.evaluation_created <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate}
| select { p.evaluation_created as evaluated_at, p.org_identifier as org, p.project_identifier as project,
p.evaluation_entity as pipeline, p.evaluation_action as action, p.policyset_name as policy_set,
p.policy_name as policy, p.policy_status as status, p.policy_severity as severity,
p.policy_deny_messages as deny_messages, p.execution_link as execution }
| order_by evaluated_at desc | limit 200

with ws as (find view "iacm:fct_workspace_events" w | filter w.updated >= cast(${start_time} as timestamp) and w.created <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${workspace_filter_predicate} and ${provisioner_filter_predicate} and ${status_filter_predicate} and ${repository_filter_predicate}
| select { w.org as org, w.project as project, distinct_count(w.unique_id) as workspaces } | group_by w.org, w.project),
ex as (find view "view:pipeline:stage_execution" se | filter se.stage_type = "IACM" and se.is_deleted = false and se.start_ts >= cast(${start_time} as timestamp) and se.start_ts <= cast(${end_time} as timestamp)
| select { se.org_identifier as org, se.project_identifier as project, distinct_count(se.plan_execution_id) as executions }
| group_by se.org_identifier, se.project_identifier)
find ws | left join ex on ex.org = ws.org and ex.project = ws.project
| select { ws.workspaces as workspaces, coalesce(ex.executions, 0) as executions, ws.project as project }

find view "view:pipeline:stage_execution" se | filter se.stage_type = "IACM" and se.is_deleted = false and se.start_ts >= cast(${start_time} as timestamp) and se.start_ts <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate}
| select { se.pipeline_identifier as pipeline, percentile(se.duration, 90) / 1000.0 as p90_seconds,
round(100.0 * count(case when se.status = "FAILED" then 1 end) / count(), 1) as failure_rate }
| group_by se.pipeline_identifier

find view "view:pipeline:stage_execution" se | filter se.stage_type = "IACM" and se.is_deleted = false and se.start_ts >= cast(${start_time} as timestamp) and se.start_ts <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate}
| select { date_trunc("week", se.start_ts) as week, distinct_count(se.plan_execution_id) as executions,
round(100.0 * count(case when se.status = "FAILED" then 1 end) / count(), 1) as failure_rate }
| group_by week | order_by week asc

with ex as (find view "view:pipeline:stage_execution" se | filter se.stage_type = "IACM" and se.is_deleted = false and se.start_ts >= cast(${start_time} as timestamp) and se.start_ts <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate}
| select { se.org_identifier as org, se.project_identifier as project, distinct_count(se.plan_execution_id) as executions }
| group_by se.org_identifier, se.project_identifier),
res as (find entity "iacm:resource" r | filter r.last_seen_millis_ts >= cast(${start_time} as timestamp) and r.last_seen_millis_ts <= cast(${end_time} as timestamp)
| select { r.org as org, r.project as project, count() as resources } | group_by r.org, r.project)
find ex | left join res on res.org = ex.org and res.project = ex.project
| select { ex.project as project, ex.executions as executions, coalesce(res.resources, 0) as resources }
| order_by executions desc | limit 20

with wv as (find view "iacm:fct_workspace_events" w | filter w.updated >= cast(${start_time} as timestamp) and w.created <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate} and ${workspace_filter_predicate} and ${provisioner_filter_predicate} and ${status_filter_predicate} and ${repository_filter_predicate}
| select { w.org as org, w.project as project, concat(w.provisioner, " ", w.provisioner_version) as engine }
| group_by w.org, w.project, engine),
ex as (find view "view:pipeline:stage_execution" se | filter se.stage_type = "IACM" and se.is_deleted = false and se.start_ts >= cast(${start_time} as timestamp) and se.start_ts <= cast(${end_time} as timestamp)
| select { se.org_identifier as org, se.project_identifier as project, count() as stages,
count(case when se.status = "FAILED" then 1 end) as failed }
| group_by se.org_identifier, se.project_identifier)
find wv | inner join ex on ex.org = wv.org and ex.project = wv.project
| select { wv.engine as engine, sum(ex.stages) as stages, sum(ex.failed) as failed,
round(100.0 * sum(ex.failed) / sum(ex.stages), 1) as failure_rate, distinct_count(wv.project) as projects }
| group_by wv.engine | order_by failure_rate desc

find view "view:pipeline:step_execution" st | filter st.step_type in ["IACMOpenTofuPlugin","IACMTerraformPlugin"] and st.start_ts >= cast(${start_time} as timestamp) and st.start_ts <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate}
| select { st.step_type as engine_plugin, count() as steps,
round(100.0 * count(case when st.status = "FAILED" then 1 end) / count(), 1) as failure_rate }
| group_by st.step_type

find view "view:pipeline:stage_execution" se | filter se.stage_type = "IACM" and se.is_deleted = false and se.start_ts >= cast(${start_time} as timestamp) and se.start_ts <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate}
| select { se.project_identifier as project, substring(cast(date_trunc("month", se.start_ts) as string), 1, 7) as month,
distinct_count(se.plan_execution_id) as executions }
| group_by se.project_identifier, month

find view "view:pipeline:step_execution" st | filter st.step_type in ["IACMApproval","HarnessApproval"] and st.start_ts >= cast(${start_time} as timestamp) and st.start_ts <= cast(${end_time} as timestamp) | filter ${org_filter_predicate} and ${project_filter_predicate}
| select { st.step_type as approval_type, st.status as status, count() as approvals,
avg(st.duration) / 1000.0 as avg_wait_s, percentile(st.duration, 90) / 1000.0 as p90_wait_s }
| group_by st.step_type, st.status | order_by approvals desc
